import { SafeTriangle } from 'prediction-cone';

const st = new SafeTriangle({ delay: 150, padding: 2 });

// When a submenu opens, activate with cursor position + submenu rect
st.activate({ x: 240, y: 180 }, submenuEl.getBoundingClientRect());

// Keep apex fresh while the cursor moves (v0.3)
document.addEventListener('pointermove', (e) => {
  st.updateApex({ x: e.clientX, y: e.clientY });

  if (!st.isInSafeZone(e.clientX, e.clientY)) {
    closeSubmenu();
  }
});

function closeSubmenu() {
  st.deactivate();
}

import { MouseTracker } from 'prediction-cone';

const tracker = new MouseTracker();
tracker.start();

function render() {
  const { x, y, vx, vy } = tracker.getState();
  const speed = Math.sqrt(vx ** 2 + vy ** 2);

  indicator.style.transform = `scale(${1 + speed * 0.5})`;

  requestAnimationFrame(render);
}

requestAnimationFrame(render);

